package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.EntityDedupService.Decision;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

class EntityHeatEventAvailabilityTest {
    EntityHeatEventProofTest h;JdbcEntityHeatEvents nativeEvents;EntityHeatEventProofService events;JdbcEntityHeatAvailability first;EntityHeatEventAvailabilityService service;Instant at;
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){h=new EntityHeatEventProofTest(){@Override GenerationJdbcStoreTest fixture(){return EntityHeatEventAvailabilityTest.this.fixture();}};h.setup();nativeEvents=new JdbcEntityHeatEvents(h.h.f.source,Set.of("fictional-owner"));events=new EntityHeatEventProofService(nativeEvents,new DataSourceTransactionManager(h.h.f.source));first=new JdbcEntityHeatAvailability(h.h.f.source,nativeEvents);at=h.h.f.clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS).plusSeconds(1);service=observer(Clock.fixed(at,ZoneOffset.UTC),h.h.f.writes);}
    EntityHeatEventAvailabilityService observer(Clock clock,SharedWriteExecutor writes){return new EntityHeatEventAvailabilityService(events,first,writes,new DataSourceTransactionManager(h.h.f.source),clock);}
    int count(){return h.h.f.count("target_type='entity_heat_first'");}
    @Test void CommittedReadPrecedesFirstAndOriginalReplaySurvivesCurrentEntityDeletion(){assertNull(service.find(h.id));assertNull(h.rr(()->service.readObserved(h.id,at)));var original=service.capture(h.id);assertEquals(at,original.availableAt());assertEquals(events.find(h.id).event(),original.event().event());h.h.f.jdbc.execute("DROP TABLE analyzed_entities");Clock unused=mock(Clock.class);when(unused.instant()).thenThrow(new AssertionError("fictional original replay must precede new clock"));assertEquals(at,observer(unused,h.h.f.writes).capture(h.id).availableAt());verifyNoInteractions(unused);assertEquals(1,count());assertEquals(0,h.h.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertFalse(original.toString().contains(h.id));}
    @Test void ExactMicrosecondCutoffUsesActualFirstAndNeverTheWriterTimestamp(){service.capture(h.id);assertNull(h.rr(()->service.readObserved(h.id,at.minusNanos(1000))));assertEquals(at,h.rr(()->service.readObserved(h.id,at)).availableAt());assertNull(h.rr(()->service.readObserved(h.id,events.readObserved(h.id).event().actedAt())));assertThrows(RuntimeException.class,()->h.rr(()->service.readObserved(h.id,at.plusNanos(1))));}
    @Test void UnknownAndIncompleteLegacyEventsNeverCreateAnObservation(){assertNull(service.capture("b".repeat(64)));h.h.f.jdbc.update("DELETE FROM jobs");h.h.write(()->{new EntityDecisionJdbcLog(new JdbcEntityDecisions(h.h.f.source),"fictional-owner",h.h.f.clock).append("fictional-key",h.h.hash,new Decision("fictional-item","fictional-new","ready",true,1L),"new","fictional-item",null,"fictional-new","Fictional old decision");return true;});assertFalse(events.find(h.id).hasCompleteTouchedFormat());assertNull(service.capture(h.id));h.h.f.jdbc.update("DELETE FROM jobs");h.h.write(()->{h.h.save(new Decision("fictional-item",null,"needs_review",false,null),"needs_review",null,null);return true;});assertTrue(events.find(h.id).hasCompleteTouchedFormat());assertNull(service.capture(h.id));assertEquals(0,count());}
    @Test void ChangedFullParentFingerprintAndMissingParentInvalidateOriginalFirst(){service.capture(h.id);h.h.f.jdbc.update("UPDATE jobs SET reason='Fictional changed reason' WHERE target_type='entity_decision'");assertNotNull(events.find(h.id));assertThrows(RuntimeException.class,()->service.find(h.id));assertThrows(RuntimeException.class,()->service.capture(h.id));h.h.f.jdbc.update("DELETE FROM jobs WHERE target_type='entity_decision'");assertThrows(RuntimeException.class,()->service.find(h.id));}
    @Test void NativeFirstRolesAliasesAndTimestampHashCorruptionCannotGrantVisibility(){for(String change:List.of("revision=1","operator_id='fictional-other'","state='failed'","root_job_id='fictional-root'","id='"+"c".repeat(64)+"'")){setup();service.capture(h.id);h.h.f.jdbc.update("UPDATE jobs SET "+change+" WHERE target_type='entity_heat_first'");assertThrows(RuntimeException.class,()->service.find(h.id));}setup();service.capture(h.id);h.h.f.jdbc.update("UPDATE jobs SET created_at=? WHERE target_type='entity_heat_first'",LocalDateTime.ofInstant(at.plusSeconds(1),ZoneOffset.UTC));assertThrows(RuntimeException.class,()->service.find(h.id));setup();service.capture(h.id);h.h.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='entity_heat_first'",new byte[32]);assertThrows(RuntimeException.class,()->service.find(h.id));}
    @Test void FirstWriterRereadsFullNativeParentAndRejectsBackwardClock(){var prepared=JdbcEntityHeatAvailability.prepare(events.find(h.id).event(),at);h.h.f.jdbc.update("UPDATE jobs SET reason='Fictional changed before writer' WHERE target_type='entity_decision'");assertThrows(RuntimeException.class,()->h.h.write(()->first.save(prepared)));assertEquals(0,count());setup();assertThrows(RuntimeException.class,()->observer(Clock.fixed(at.minusSeconds(2),ZoneOffset.UTC),h.h.f.writes).capture(h.id));assertEquals(0,count());var calls=new java.util.concurrent.atomic.AtomicInteger();Clock backward=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return calls.getAndIncrement()==0?at:at.minusNanos(1000);}};assertThrows(RuntimeException.class,()->observer(backward,h.h.f.writes).capture(h.id));assertEquals(0,count());}
    @Test void AppendFailureRollsBackAndActualCommitAcknowledgementLossKeepsOneFirst(){h.h.f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_heat_first_failure CHECK(target_type IS NULL OR target_type<>'entity_heat_first')");assertThrows(RuntimeException.class,()->service.capture(h.id));assertEquals(0,count());h.h.f.jdbc.execute(h.h.f.source instanceof org.h2.jdbcx.JdbcDataSource?"ALTER TABLE jobs DROP CONSTRAINT fictional_heat_first_failure":"ALTER TABLE jobs DROP CHECK fictional_heat_first_failure");var fault=new DataSourceTransactionManager(h.h.f.source){boolean lost;@Override protected void doCommit(DefaultTransactionStatus s){super.doCommit(s);if(!lost&&!TransactionSynchronizationManager.isCurrentTransactionReadOnly()){lost=true;throw new TransactionSystemException("fictional first observer ACK lost");}}};var writes=new SharedWriteExecutor(new JdbcSharedWriteEntry(h.h.f.source),fault,()->25,n->{});assertEquals(at,observer(Clock.fixed(at,ZoneOffset.UTC),writes).capture(h.id).availableAt());assertEquals(at,service.capture(h.id).availableAt());assertEquals(1,count());}
    @Test void ConcurrentObserversKeepExactlyOneOriginalFirst() throws Exception {try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var a=pool.submit(()->{start.await();return service.capture(h.id);});var b=pool.submit(()->{start.await();return observer(Clock.fixed(at.plusSeconds(1),ZoneOffset.UTC),h.h.f.writes).capture(h.id);});start.countDown();var first=a.get(5,TimeUnit.SECONDS);var second=b.get(5,TimeUnit.SECONDS);assertEquals(first.availableAt(),second.availableAt());assertEquals(1,count());}}
    @Test void UncommittedEventCannotCreateFirstObservation() throws Exception {h.h.f.jdbc.update("DELETE FROM jobs");try(var pool=Executors.newSingleThreadExecutor()){var written=new CountDownLatch(1);var commit=new CountDownLatch(1);var future=pool.submit(()->{var tx=new TransactionTemplate(new DataSourceTransactionManager(h.h.f.source));tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);return tx.execute(s->{new JdbcSharedWriteEntry(h.h.f.source).lock();h.h.save(new Decision("fictional-item","fictional-new","ready",true,1L),"new",null,"fictional-new");written.countDown();try{if(!commit.await(5,TimeUnit.SECONDS))throw new IllegalStateException("fictional commit wait");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return true;});});try{assertTrue(written.await(5,TimeUnit.SECONDS));assertNull(service.capture(h.id));assertEquals(0,count());}finally{commit.countDown();}assertTrue(future.get(5,TimeUnit.SECONDS));assertEquals(at,service.capture(h.id).availableAt());assertEquals(1,count());}}
    @Test void ExplicitReadonlyRrAndColdActualDependenciesAreRequired(){assertThrows(RuntimeException.class,()->service.readObserved(h.id,at));assertThrows(RuntimeException.class,()->h.h.write(()->service.readObserved(h.id,at)));var tx=new TransactionTemplate(new DataSourceTransactionManager(h.h.f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertThrows(RuntimeException.class,()->tx.execute(s->service.readObserved(h.id,at)));assertThrows(RuntimeException.class,()->h.rr(()->service.capture(h.id)));var source=mock(javax.sql.DataSource.class);var manager=mock(PlatformTransactionManager.class);var clock=mock(Clock.class);var writes=mock(SharedWriteExecutor.class);var nativePort=new JdbcEntityHeatEvents(source);new EntityHeatEventAvailabilityService(new EntityHeatEventProofService(nativePort,manager),new JdbcEntityHeatAvailability(source,nativePort),writes,manager,clock);verifyNoInteractions(source,manager,clock,writes);}
}
